import{z as s,x as d,o as t,c as B,q as r,j as o,D as l,d as E,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"光刻友好设计 LFD","description":"","frontmatter":{"title":"光刻友好设计 LFD","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lfd.md","filePath":"litho/lfd.md","lastUpdated":1791063341000}'),D={name:"litho/lfd.md"};function p(h,a,F,L,f,T){const i=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="光刻友好设计-lfd" tabindex="-1">光刻友好设计 LFD <a class="header-anchor" href="#光刻友好设计-lfd" aria-label="Permalink to &quot;光刻友好设计 LFD&quot;">​</a></h1><div class="epigraph"><p>友好不是「画得好看」，是把单元和布线预先投影到可印、可分解、可转印的子集，让全芯片核少遇见必然失败的邻域。</p><footer>—— 对照 Mentor Calibre LFD 一类工具的公开定位；DTCO 与光刻友好设计的产线通称</footer></div><p><a href="/litho/full-chip-simulation-cost">上一课</a>把全场仿真收成算力合同。缺口是设计侧：若库和布线仍制造核修不回来的二维组合，再便宜的卷积也只是更快报红。<a href="/litho/dtco-patterning">DTCO</a> 已在主干谈协同；本课钉 LFD 作为签核门的设计入口。哪些红是「长得像已知杀手」而不是再跑一遍仿真，留给<a href="/litho/pattern-matching">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LFD（lithography-friendly design / litho-friendly design）把计算光刻前向接到单元库与布线阶段：在 TAPOUT 之前，用同一套紧凑模型抽检标准单元、SRAM、互连 clips，找出 PV-band 越界、桥连、线端缩短、via 覆盖不足。它不是第二套 DRC 几何规则，而是<strong>带工艺模型的早期签核</strong>。</p><p>缺口是<strong>何时在设计里花仿真</strong>，不是重写 SMO。<a href="/litho/hotspot-pv">热点与 PV</a> 已定义什么叫先死的图形；LFD 问的是这些图形能不能在库冻结前被消灭，而不是留给 OPC 工程师通宵。</p><h3 id="lfd-不是放宽-drc" tabindex="-1">LFD 不是放宽 DRC <a class="header-anchor" href="#lfd-不是放宽-drc" aria-label="Permalink to &quot;LFD 不是放宽 DRC&quot;">​</a></h3><p>有人把 LFD 理解成「模型说能印就允许破规则」。方向反了：LFD 用模型证明规则该更严、或该改成单向金属加切线。规则仍是合同；模型是产生与验证合同的仪器。把 LFD 当破例通道，签核版本会分裂。</p><p><span class="marginnote">术语翻译：TAPOUT 指版图定稿、交付做掩模的节点；PV-band 是把剂量、焦点等工艺变化范围投影到同一图形上，轮廓铺开成的一条「可能地带」——带越宽、离失败越近，带压线即热点。</span></p><p><span class="marginnote">LFD 用的模型必须与 OPC/LRC 同版本、同刻蚀核。用实验室 3D 去签库、用紧凑核去签芯片，友好会在全场蒸发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：候选库、布线方向约束、via 网格、多重分解选项。动作：对代表 clips 跑 OPC 级前向或快速 PV，输出热点表与建议（加间隔、改轨道、禁某 jog）。循环停在库 freeze，而不是每块产品版再发明一套友好。与 <a href="/litho/smo">SMO</a> 的分工：SMO 优化光源与掩模；LFD 优化允许存在的多边形。</p>',12)),(t(),o(n,null,{default:l(()=>[A(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%E4%BB%8B%E5%85%A5%3F%22%7D%20--%3E%20LIBSTEP%5B%22%E5%BA%93%20%2F%20%E5%B8%83%E7%BA%BF%E9%98%B6%E6%AE%B5%22%5D%0A%20%20Q%20--%3E%20MASKSTEP%5B%22%E6%8E%A9%E6%A8%A1%E9%98%B6%E6%AE%B5%22%5D%0A%20%20LIBSTEP%20--%3E%20LFD%5B%22LFD%3A%20%E5%88%A0%E6%8E%89%E6%88%96%E6%94%B9%E5%86%99%E5%9D%8F%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20LIBSTEP%20--%3E%20SMO%5B%22SMO%3A%20%E4%BC%98%E5%8C%96%E5%85%89%E6%BA%90%E9%85%8D%E5%90%88%22%5D%0A%20%20MASKSTEP%20--%3E%20OPC%5B%22OPC%20%2F%20ILT%3A%20%E8%A1%A5%E5%81%BF%E6%8E%A9%E6%A8%A1%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20LFD%20--%3E%20OUT1%5B%22%E8%BE%93%E5%87%BA%3A%20%E5%B8%A6%E7%89%88%E6%9C%AC%E7%9A%84%E7%BA%A6%E6%9D%9F%E6%96%87%E4%BB%B6%22%5D%0A%20%20OPC%20--%3E%20OUT2%5B%22%E8%BE%93%E5%87%BA%3A%20%E6%8E%A9%E6%A8%A1%E7%89%88%E5%9B%BE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"金属层尤其吃 LFD：二维拐角和 tip-to-tip 是全芯片账单的主要制造者。via 覆盖与下层金属协同，本课只点名，细节在本课序末课。",-1)),a[4]||(a[4]=e("p",null,"库 freeze 之后仍会有布线器生长出表外 jog。LFD 的日常形态是：新产品 TAPOUT 前对增量 clips 再跑一轮，而不是每夜全库。Calibre LFD 一类工具的公开定位正是这条「带模型的设计检查」，不是第二套光学引擎。SRAM 库与逻辑库必须分开跑 LFD：同一套「友好」在 bitcell 上可能非法。输出是带版本的约束文件，而不是一封邮件里的热点截图。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"设计多边形进入成像算子前，已被轨道高度、最小间隔、单向偏好投影。LFD 是这条投影的带模型反馈：前向说某 jog 在离焦下桥连，就从库里删掉，而不是指望 ILT 把 jog 修圆。算力课的含义是：删掉一个系统坏图形，等于少付全场每一处相似邻域的迭代。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：LFD 像在菜单定稿前把每道菜先试做一遍，删掉厨房做不出来的菜式；OPC 像硬着头皮按原菜单上菜、再偷偷修一修摆盘——菜还是那道难做的菜，只是每桌都多花一道工。")],-1)),(t(),o(n,null,{default:l(()=>[A(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E5%80%99%E9%80%89%E5%BA%93%20%2F%20%E5%B8%83%E7%BA%BF%22%5D%20--%3E%20LFD%5B%22%E5%B8%A6%E6%A8%A1%E5%9E%8B%E7%9A%84%E6%97%A9%E6%9C%9F%E5%89%8D%E5%90%91%22%5D%0A%20%20LFD%20--%3E%20HOT%5B%22%E7%83%AD%E7%82%B9%E8%A1%A8%22%5D%0A%20%20HOT%20--%3E%20FIX%5B%22%E6%94%B9%E5%BA%93%E6%88%96%E5%8A%A0%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20FIX%20--%3E%20LIB%0A%20%20LIB%20--%3E%20TAP%5B%22%E8%BF%9B%E5%85%A5%20OPC%20%2F%20LRC%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p>冻结后的库进入全芯片，LRC 仍会见到布线器新组合。LFD 降低的是系统坏图形的先验密度，不是签发「布线后不必再查」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LFD 不替代全芯片 LRC，也不替代掩模 MRC。不把某 EDA 商标写成物理定律。随机缺陷率通常不在 LFD 默认目标里，除非明确加随机窗。</p><p>后课默认：库应在模型反馈下冻结；下一课用图形匹配把「已知杀手」从全场里廉价扫出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LFD 是带同一套光刻–刻蚀核的设计早期签核，用来冻结友好库。</li><li>它收紧或改写规则，不是发破例通行证。</li><li>删系统坏图形，直接降低全芯片仿真账单。</li><li>出处：Calibre LFD 公开定位；imec / 计算光刻对 litho-friendly 库的论述。</li></ul>',6))])}const C=s(D,[["render",p]]);export{P as __pageData,C as default};
